// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.classifierimport com.roshan.persona.brain.intent.Intentimport kotlin.reflect.KClassimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Stage 2: Keyword + Token Matcher. * * Tokenizes input, stems tokens, matches against per-intent keyword * dictionaries. Score = (matched_keywords / total_keywords). * * Threshold: > 0.65 → match. Handles ~25% of intents (after regex). * * Stemming is intentionally simple (Porter-lite) — covers common English * inflections (-s, -es, -ing, -ed, -ly) without external dep. * * @see <a href="docs/spec/module2-spec-review.pdf">§4.1 Stage 2</a> */@Singletonclass KeywordIntentMatcher @Inject constructor() {    private val keywordSets: List<KeywordIntentSet> = listOf(        KeywordIntentSet(            intentType = Intent.Call::class,            keywords = setOf("call", "phone", "ring", "dial"),            optionalKeywords = setOf("mom", "dad", "home", "office"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.Call(contact = extractContact(tokens)) },        ),        KeywordIntentSet(            intentType = Intent.SendSms::class,            keywords = setOf("sms", "text", "message"),            optionalKeywords = setOf("send", "to"),            minMatchRatio = 0.5f,            factory = { _ -> Intent.SendSms(contact = null, message = null) },        ),        KeywordIntentSet(            intentType = Intent.SendEmail::class,            keywords = setOf("email", "mail"),            optionalKeywords = setOf("send", "compose"),            minMatchRatio = 0.5f,            factory = { _ -> Intent.SendEmail(to = null, subject = null, body = null) },        ),        KeywordIntentSet(            intentType = Intent.OpenApp::class,            keywords = setOf("open", "launch", "start", "run"),            optionalKeywords = setOf("app", "application"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.OpenApp(appName = extractAppName(tokens)) },        ),        KeywordIntentSet(            intentType = Intent.SearchWeb::class,            keywords = setOf("search", "find", "look", "google"),            optionalKeywords = setOf("for", "up", "online", "web"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.SearchWeb(query = extractQuery(tokens)) },        ),        KeywordIntentSet(            intentType = Intent.SetReminder::class,            keywords = setOf("remind", "reminder"),            optionalKeywords = setOf("me", "to", "about"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.SetReminder(text = extractReminderText(tokens)) },        ),        KeywordIntentSet(            intentType = Intent.CreateNote::class,            keywords = setOf("note", "write", "jot", "take"),            optionalKeywords = setOf("down", "this", "that", "a"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.CreateNote(text = extractNoteText(tokens)) },        ),        KeywordIntentSet(            intentType = Intent.Summarize::class,            keywords = setOf("summarize", "summary", "tldr", "gist"),            optionalKeywords = setOf("this", "of"),            minMatchRatio = 0.5f,            factory = { tokens -> Intent.Summarize(target = null, raw = tokens.joinToString(" ")) },        ),        KeywordIntentSet(            intentType = Intent.Explain::class,            keywords = setOf("explain", "what", "how", "why", "describe"),            optionalKeywords = setOf("is", "are", "do", "does"),            minMatchRatio = 0.4f,            factory = { tokens -> Intent.Explain(topic = null, raw = tokens.joinToString(" ")) },        ),        KeywordIntentSet(            intentType = Intent.Translate::class,            keywords = setOf("translate", "translation"),            optionalKeywords = setOf("to", "in"),            minMatchRatio = 0.5f,            factory = { tokens -> Intent.Translate(text = null, targetLanguage = null) },        ),        KeywordIntentSet(            intentType = Intent.CreateAutomation::class,            keywords = setOf("when", "automate", "automation", "trigger"),            optionalKeywords = setOf("i", "get", "arrive", "leave"),            minMatchRatio = 0.4f,            factory = { _ -> Intent.CreateAutomation(trigger = null, action = null) },        ),        KeywordIntentSet(            intentType = Intent.MultiStep::class,            keywords = setOf("and", "then", "after", "next"),            optionalKeywords = setOf("that", "do"),            minMatchRatio = 0.5f,            factory = { tokens -> Intent.MultiStep(description = tokens.joinToString(" "), raw = tokens.joinToString(" ")) },        ),    )    /**     * Try to match [input] against keyword sets.     *     * @return [KeywordMatch] with raw score (0.0-1.0) if any match ≥ threshold, null otherwise.     */    fun match(input: String): KeywordMatch? {        val tokens = tokenize(input)        if (tokens.isEmpty()) return null        var bestMatch: KeywordMatch? = null        var bestScore = 0f        for (set in keywordSets) {            val score = scoreMatch(tokens, set)            if (score >= set.minMatchRatio && score > bestScore) {                bestScore = score                bestMatch = KeywordMatch(                    intent = set.factory(tokens),                    rawScore = score,                    intentType = set.intentType,                )            }        }        return bestMatch    }    /** Tokenize input: lowercase, split on non-alphanumeric, stem. */    private fun tokenize(input: String): List<String> {        return input            .lowercase()            .split(Regex("[^a-z0-9]+"))            .filter { it.isNotBlank() }            .map { stem(it) }    }    /** Simple stemmer — strips common English suffixes. */    private fun stem(word: String): String {        val suffixes = listOf("ing", "edly", "ed", "ly", "es", "s")        for (suffix in suffixes) {            if (word.length > suffix.length + 2 && word.endsWith(suffix)) {                return word.dropLast(suffix.length)            }        }        return word    }    /** Score: matched keywords / total keywords. Optional keywords add bonus.     *  Boost: if a keyword appears as the first token, it's the primary verb — boost score. */    private fun scoreMatch(tokens: List<String>, set: KeywordIntentSet): Float {        if (set.keywords.isEmpty()) return 0f        val stemmedTokens = tokens.map { stem(it) }        val matchedRequired = set.keywords.count { kw -> stemmedTokens.contains(stem(kw)) }        val matchedOptional = set.optionalKeywords.count { kw -> stemmedTokens.contains(stem(kw)) }        val requiredRatio = matchedRequired.toFloat() / set.keywords.size        val optionalBonus = if (set.optionalKeywords.isNotEmpty()) {            (matchedOptional.toFloat() / set.optionalKeywords.size) * 0.2f        } else {            0f        }        // Boost: if first token matches a keyword, it's likely the primary verb        val firstTokenBoost = if (stemmedTokens.isNotEmpty()) {            val firstToken = stemmedTokens.first()            if (set.keywords.any { stem(it) == firstToken }) 0.3f else 0f        } else {            0f        }        return requiredRatio + optionalBonus + firstTokenBoost    }    /** Extract contact name from tokens (heuristic — NER is in Stage 4). */    private fun extractContact(tokens: List<String>): String? {        val stopWords = setOf("call", "phone", "ring", "dial", "to", "the", "my", "mom", "dad")        val contact = tokens.filter { it !in stopWords }.take(2).joinToString(" ")        return contact.ifBlank { null }    }    /** Extract app name from tokens (heuristic). */    private fun extractAppName(tokens: List<String>): String? {        val stopWords = setOf("open", "launch", "start", "run", "the", "app", "application")        val appName = tokens.filter { it !in stopWords }.joinToString(" ")        return appName.ifBlank { null }    }    /** Extract search query (everything after the verb). */    private fun extractQuery(tokens: List<String>): String? {        val stopIdx = tokens.indexOfFirst { it in setOf("search", "find", "look", "google") }        if (stopIdx == -1) return null        val query = tokens.drop(stopIdx + 1).joinToString(" ")        return query.ifBlank { null }    }    /** Extract reminder text (everything after "remind me to"). */    private fun extractReminderText(tokens: List<String>): String? {        val remindIdx = tokens.indexOfFirst { it == "remind" || it == "reminder" }        if (remindIdx == -1) return null        val text = tokens.drop(remindIdx + 1)            .dropWhile { it in setOf("me", "to", "about") }            .joinToString(" ")        return text.ifBlank { null }    }    /** Extract note text. */    private fun extractNoteText(tokens: List<String>): String? {        val noteIdx = tokens.indexOfFirst { it in setOf("note", "write", "jot") }        if (noteIdx == -1) return null        val text = tokens.drop(noteIdx + 1)            .dropWhile { it in setOf("down", "this", "that") }            .joinToString(" ")        return text.ifBlank { null }    }    /** Pre-defined keyword set for one intent. */    private data class KeywordIntentSet(        val intentType: KClass<out Intent>,        val keywords: Set<String>,        val optionalKeywords: Set<String>,        val minMatchRatio: Float,        val factory: (List<String>) -> Intent,    )    /** Result of keyword match. */    data class KeywordMatch(        val intent: Intent,        val rawScore: Float,  // 0.0-1.0+ (can exceed 1.0 due to optional bonus)        val intentType: KClass<out Intent>,    )}